    $('#tamHow', sl).innerHTML = t.how.map((h, k) => '<p><b>' + (k + 1) + '.</b> ' + esc(h).replace(/\[([^\]]*)\]/g, '<span class="fill">[$1]</span>') + '</p>').join('');
